const personalRows=[["account","User"],["subscription","Wallet"],["notifications","Bell"],["budget","SlidersHorizontal"],["categories","Boxes"],["data","Database"],["appearance","Palette"],["security","ShieldCheck"],["workspace","Building2"],["support","LifeBuoy"]] as const;
